 CREATE OR REPLACE FUNCTION public.finance_sku_payout_count_summary(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid)+
  RETURNS jsonb                                                                                                                                                                                                 +
  LANGUAGE plpgsql                                                                                                                                                                                              +
  SECURITY DEFINER                                                                                                                                                                                              +
  SET search_path TO 'public'                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                  +
  declare                                                                                                                                                                                                       +
   v_start date := coalesce(p_start, current_date - 30);                                                                                                                                                        +
   v_end date := coalesce(p_end, current_date);                                                                                                                                                                 +
   v_user_id uuid;                                                                                                                                                                                              +
   v_tenant_id uuid;                                                                                                                                                                                            +
   v_marketplace text := lower(trim(coalesce(p_marketplace, '')));                                                                                                                                              +
   v_result jsonb;                                                                                                                                                                                              +
 begin                                                                                                                                                                                                          +
   begin                                                                                                                                                                                                        +
     v_user_id := nullif(                                                                                                                                                                                       +
       coalesce(                                                                                                                                                                                                +
         auth.uid()::text,                                                                                                                                                                                      +
         (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')                                                                                                                             +
       ),                                                                                                                                                                                                       +
       ''                                                                                                                                                                                                       +
     )::uuid;                                                                                                                                                                                                   +
   exception when others then                                                                                                                                                                                   +
     v_user_id := null;                                                                                                                                                                                         +
   end;                                                                                                                                                                                                         +
                                                                                                                                                                                                                +
   select coalesce(u.tenant_id, current_setting('app.current_tenant_id', true)::uuid)                                                                                                                           +
     into v_tenant_id                                                                                                                                                                                           +
   from public.users u                                                                                                                                                                                          +
   where u.user_id = v_user_id                                                                                                                                                                                  +
   limit 1;                                                                                                                                                                                                     +
                                                                                                                                                                                                                +
   if v_tenant_id is null then                                                                                                                                                                                  +
     v_tenant_id := coalesce(current_setting('app.current_tenant_id', true)::uuid, (select tenant_id from public.users limit 1));                                                                               +
   end if;                                                                                                                                                                                                      +
                                                                                                                                                                                                                +
   if v_tenant_id is null then return '{"ok":false,"error":"tenant_id required"}'::jsonb; end if;                                                                                                               +
                                                                                                                                                                                                                +
   with valid_orders as (                                                                                                                                                                                       +
     select                                                                                                                                                                                                     +
       o.tenant_id,                                                                                                                                                                                             +
       o.marketplace_order_id,                                                                                                                                                                                  +
       o.marketplace_account_id,                                                                                                                                                                                +
       o.marketplace,                                                                                                                                                                                           +
       o.external_order_id,                                                                                                                                                                                     +
       o.order_sn,                                                                                                                                                                                              +
       o.order_status,                                                                                                                                                                                          +
       o.status,                                                                                                                                                                                                +
       coalesce(nullif(o.external_order_id, ''), nullif(o.order_sn, ''), o.marketplace_order_id::text) as order_key,                                                                                            +
       (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta') as order_ts_wib,                                                                                     +
       (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date as order_date_wib                                                                              +
     from public.marketplace_orders o                                                                                                                                                                           +
     where o.tenant_id = v_tenant_id                                                                                                                                                                            +
       and (v_marketplace = '' or lower(coalesce(o.marketplace, '')) = v_marketplace)                                                                                                                           +
       and (p_account_id is null or o.marketplace_account_id = p_account_id)                                                                                                                                    +
       and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date >= v_start                                                                                 +
       and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date <= v_end                                                                                   +
   ),                                                                                                                                                                                                           +
   finance_by_order as (                                                                                                                                                                                        +
     select                                                                                                                                                                                                     +
       coalesce(nullif(order_id, ''), marketplace_order_id::text, 'no_order_id_' || md5(random()::text)) as order_key,                                                                                          +
       marketplace_account_id,                                                                                                                                                                                  +
       marketplace,                                                                                                                                                                                             +
       max(settlement_status) as settlement_status,                                                                                                                                                             +
       sum(coalesce(payout_amount, net_settlement, 0)) as payout_total                                                                                                                                          +
     from public.marketplace_finance_reports                                                                                                                                                                    +
     where tenant_id = v_tenant_id                                                                                                                                                                              +
       and (v_marketplace = '' or lower(coalesce(marketplace, '')) = v_marketplace)                                                                                                                             +
       and (p_account_id is null or marketplace_account_id = p_account_id)                                                                                                                                      +
       and coalesce(settlement_date, period_start) >= v_start                                                                                                                                                   +
       and coalesce(settlement_date, period_start) <= v_end                                                                                                                                                     +
     group by 1, 2, 3                                                                                                                                                                                           +
   ),                                                                                                                                                                                                           +
   detail as (                                                                                                                                                                                                  +
     select                                                                                                                                                                                                     +
       vo.marketplace_account_id,                                                                                                                                                                               +
       vo.marketplace,                                                                                                                                                                                          +
       vo.order_key,                                                                                                                                                                                            +
       vo.order_status,                                                                                                                                                                                         +
       vo.order_date_wib,                                                                                                                                                                                       +
       oi.marketplace_sku_id,                                                                                                                                                                                   +
       oi.quantity as qty,                                                                                                                                                                                      +
       coalesce(nullif(oi.marketplace_seller_sku, ''), nullif(oi.seller_sku, '')) as marketplace_seller_sku,                                                                                                    +
       coalesce(nullif(oi.mapped_local_sku, ''), nullif(oi.local_sku, ''), 'Unmapped') as local_sku,                                                                                                            +
       coalesce(nullif(oi.product_name, ''), nullif(oi.marketplace_product_name, ''), nullif(oi.local_product_name, '')) as product_name,                                                                       +
       coalesce(nullif(oi.variant_name, ''), nullif(oi.marketplace_variant_name, ''), nullif(oi.variation_name, '')) as variant_name,                                                                           +
       greatest(                                                                                                                                                                                                +
         coalesce(oi.gross_amount, 0),                                                                                                                                                                          +
         coalesce(oi.paid_amount, 0),                                                                                                                                                                           +
         coalesce(oi.unit_gross_amount, 0) * greatest(coalesce(nullif(oi.quantity, 0), nullif(oi.qty, 0), 1), 1)                                                                                                +
       ) as gross_line                                                                                                                                                                                          +
     from valid_orders vo                                                                                                                                                                                       +
     join public.marketplace_order_items oi                                                                                                                                                                     +
       on oi.tenant_id = vo.tenant_id                                                                                                                                                                           +
       and oi.marketplace_order_id = vo.marketplace_order_id                                                                                                                                                    +
     where oi.marketplace_sku_id is not null                                                                                                                                                                    +
       and nullif(trim(oi.marketplace_sku_id), '') is not null                                                                                                                                                  +
       and nullif(trim(oi.marketplace_sku_id), '-') is not null                                                                                                                                                 +
       and nullif(trim(coalesce(oi.marketplace_seller_sku, oi.seller_sku, '')), '') is not null                                                                                                                 +
       and nullif(trim(coalesce(oi.marketplace_seller_sku, oi.seller_sku, '')), '-') is not null                                                                                                                +
   ),                                                                                                                                                                                                           +
   hpp_sku as (                                                                                                                                                                                                 +
     select tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, '')) as marketplace_sku_id,                                                                                                     +
            max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,                                                                                                                                    +
            max(nullif(local_sku, '')) as mapped_local_sku                                                                                                                                                      +
     from public.marketplace_variant_hpp_mappings                                                                                                                                                               +
     where coalesce(is_active, true) is true and nullif(marketplace_sku_id, '') is not null                                                                                                                     +
       and tenant_id = v_tenant_id                                                                                                                                                                              +
     group by tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, ''))                                                                                                                          +
   ),                                                                                                                                                                                                           +
   hpp_seller as (                                                                                                                                                                                              +
     select tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, '')) as marketplace_seller_sku,                                                                                             +
            max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,                                                                                                                                    +
            max(nullif(local_sku, '')) as mapped_local_sku                                                                                                                                                      +
     from public.marketplace_variant_hpp_mappings                                                                                                                                                               +
     where coalesce(is_active, true) is true and nullif(marketplace_seller_sku, '') is not null                                                                                                                 +
       and tenant_id = v_tenant_id                                                                                                                                                                              +
     group by tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, ''))                                                                                                                      +
   ),                                                                                                                                                                                                           +
   hpp_local as (                                                                                                                                                                                               +
     select tenant_id, marketplace_account_id, lower(nullif(local_sku, '')) as local_sku,                                                                                                                       +
            max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,                                                                                                                                    +
            max(nullif(local_sku, '')) as mapped_local_sku                                                                                                                                                      +
     from public.marketplace_variant_hpp_mappings                                                                                                                                                               +
     where coalesce(is_active, true) is true and nullif(local_sku, '') is not null                                                                                                                              +
       and tenant_id = v_tenant_id                                                                                                                                                                              +
     group by tenant_id, marketplace_account_id, lower(nullif(local_sku, ''))                                                                                                                                   +
   ),                                                                                                                                                                                                           +
   enriched as (                                                                                                                                                                                                +
     select                                                                                                                                                                                                     +
       d.marketplace_account_id,                                                                                                                                                                                +
       d.marketplace,                                                                                                                                                                                           +
       d.order_key,                                                                                                                                                                                             +
       d.order_status,                                                                                                                                                                                          +
       d.order_date_wib,                                                                                                                                                                                        +
       d.marketplace_sku_id,                                                                                                                                                                                    +
       d.qty,                                                                                                                                                                                                   +
       d.marketplace_seller_sku,                                                                                                                                                                                +
       d.local_sku,                                                                                                                                                                                             +
       d.product_name,                                                                                                                                                                                          +
       d.variant_name,                                                                                                                                                                                          +
       d.gross_line,                                                                                                                                                                                            +
       fbo.payout_total as order_payout,                                                                                                                                                                        +
       fbo.settlement_status,                                                                                                                                                                                   +
       sum(nullif(d.gross_line, 0)) over (partition by d.marketplace_account_id, d.order_key) as gross_order_scope,                                                                                             +
       sum(d.qty) over (partition by d.marketplace_account_id, d.order_key) as qty_order_scope,                                                                                                                 +
       coalesce(hs.hpp, hsel.hpp, hl.hpp, 0)::numeric as unit_hpp,                                                                                                                                              +
       coalesce(hs.mapped_local_sku, hsel.mapped_local_sku, hl.mapped_local_sku, d.local_sku) as live_local_sku                                                                                                 +
     from detail d                                                                                                                                                                                              +
     left join finance_by_order fbo                                                                                                                                                                             +
       on fbo.marketplace_account_id = d.marketplace_account_id                                                                                                                                                 +
       and fbo.order_key = d.order_key                                                                                                                                                                          +
     left join hpp_sku hs on hs.marketplace_account_id = d.marketplace_account_id and hs.marketplace_sku_id = lower(nullif(d.marketplace_sku_id, ''))                                                           +
     left join hpp_seller hsel on hsel.marketplace_account_id = d.marketplace_account_id and hsel.marketplace_seller_sku = lower(nullif(d.marketplace_seller_sku, ''))                                          +
     left join hpp_local hl on hl.marketplace_account_id = d.marketplace_account_id and hl.local_sku = lower(nullif(d.local_sku, ''))                                                                           +
   ),                                                                                                                                                                                                           +
   allocated as (                                                                                                                                                                                               +
     select                                                                                                                                                                                                     +
       *,                                                                                                                                                                                                       +
       case                                                                                                                                                                                                     +
         when coalesce(order_payout, 0) = 0 then 0                                                                                                                                                              +
         when coalesce(gross_order_scope, 0) > 0 and gross_line > 0 then order_payout * gross_line / gross_order_scope                                                                                          +
         when coalesce(qty_order_scope, 0) > 0 then order_payout * qty / qty_order_scope                                                                                                                        +
         else order_payout                                                                                                                                                                                      +
       end as payout_allocated                                                                                                                                                                                  +
     from enriched                                                                                                                                                                                              +
   ),                                                                                                                                                                                                           +
   calculated as (                                                                                                                                                                                              +
     select                                                                                                                                                                                                     +
       a.*,                                                                                                                                                                                                     +
       upper(coalesce(a.order_status, '')) as order_status_upper,                                                                                                                                               +
       case                                                                                                                                                                                                     +
         when upper(coalesce(a.order_status, '')) like '%CANCEL%'                                                                                                                                               +
           or upper(coalesce(a.order_status, '')) like '%REFUND%'                                                                                                                                               +
           or upper(coalesce(a.order_status, '')) like '%RETURN%' then 'Cancel/Refund/Return'                                                                                                                   +
         when coalesce(a.order_payout, 0) = 0 then 'Belum Payout'                                                                                                                                               +
         when a.payout_allocated < 0 then 'Payout Minus'                                                                                                                                                        +
         else coalesce(nullif(a.settlement_status, ''), 'Settled')                                                                                                                                              +
       end as payout_status_clean                                                                                                                                                                               +
     from allocated a                                                                                                                                                                                           +
   ),                                                                                                                                                                                                           +
   flagged as (                                                                                                                                                                                                 +
     select                                                                                                                                                                                                     +
       c.*,                                                                                                                                                                                                     +
       (                                                                                                                                                                                                        +
         c.order_status_upper like '%CANCEL%'                                                                                                                                                                   +
         or c.order_status_upper like '%REFUND%'                                                                                                                                                                +
         or c.order_status_upper like '%RETURN%'                                                                                                                                                                +
         or upper(c.payout_status_clean) like '%CANCEL%'                                                                                                                                                        +
         or upper(c.payout_status_clean) like '%REFUND%'                                                                                                                                                        +
         or upper(c.payout_status_clean) like '%RETURN%'                                                                                                                                                        +
       ) as is_cancel_refund_return                                                                                                                                                                             +
     from calculated c                                                                                                                                                                                          +
   ),                                                                                                                                                                                                           +
   grouped as (                                                                                                                                                                                                 +
     select                                                                                                                                                                                                     +
       marketplace_account_id,                                                                                                                                                                                  +
       marketplace,                                                                                                                                                                                             +
       coalesce(nullif(marketplace_sku_id, ''), '-') as marketplace_sku_id,                                                                                                                                     +
       coalesce(nullif(marketplace_seller_sku, ''), '-') as marketplace_seller_sku,                                                                                                                             +
       coalesce(nullif(local_sku, ''), '-') as local_sku,                                                                                                                                                       +
       max(product_name) as product_name,                                                                                                                                                                       +
       max(variant_name) as variant_name,                                                                                                                                                                       +
       max(unit_hpp) as unit_hpp,                                                                                                                                                                               +
                                                                                                                                                                                                                +
       count(*) filter (                                                                                                                                                                                        +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) <> 0                                                                                                                                                               +
       )::int as paid_rows,                                                                                                                                                                                     +
                                                                                                                                                                                                                +
       count(*) filter (                                                                                                                                                                                        +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) = 0                                                                                                                                                                +
           and payout_status_clean = 'Belum Payout'                                                                                                                                                             +
       )::int as unpaid_rows,                                                                                                                                                                                   +
                                                                                                                                                                                                                +
       coalesce(sum(qty) filter (                                                                                                                                                                               +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) <> 0                                                                                                                                                               +
       ), 0)::numeric as paid_qty,                                                                                                                                                                              +
                                                                                                                                                                                                                +
       coalesce(sum(qty) filter (                                                                                                                                                                               +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) = 0                                                                                                                                                                +
           and payout_status_clean = 'Belum Payout'                                                                                                                                                             +
       ), 0)::numeric as unpaid_qty,                                                                                                                                                                            +
                                                                                                                                                                                                                +
       coalesce(sum(gross_line) filter (                                                                                                                                                                        +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) <> 0                                                                                                                                                               +
       ), 0)::numeric as paid_gross_total,                                                                                                                                                                      +
                                                                                                                                                                                                                +
       coalesce(sum(gross_line) filter (                                                                                                                                                                        +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) = 0                                                                                                                                                                +
           and payout_status_clean = 'Belum Payout'                                                                                                                                                             +
       ), 0)::numeric as unpaid_gross_total,                                                                                                                                                                    +
                                                                                                                                                                                                                +
       coalesce(sum(payout_allocated) filter (                                                                                                                                                                  +
         where not is_cancel_refund_return                                                                                                                                                                      +
           and coalesce(payout_allocated, 0) <> 0                                                                                                                                                               +
       ), 0)::numeric as paid_payout_total,                                                                                                                                                                     +
                                                                                                                                                                                                                +
       count(*)::int as all_rows,                                                                                                                                                                               +
       coalesce(sum(qty), 0)::numeric as all_qty,                                                                                                                                                               +
       coalesce(sum(qty * unit_hpp), 0)::numeric as hpp_total                                                                                                                                                   +
     from flagged                                                                                                                                                                                               +
     group by 1, 2, 3, 4, 5                                                                                                                                                                                     +
   )                                                                                                                                                                                                            +
   select jsonb_build_object(                                                                                                                                                                                   +
     'ok', true,                                                                                                                                                                                                +
     'version', 'finance_sku_payout_count_summary_2026_07_06_v6_clean_skus',                                                                                                                                    +
     'start', v_start,                                                                                                                                                                                          +
     'end', v_end,                                                                                                                                                                                              +
     'rows', coalesce(jsonb_agg(jsonb_build_object(                                                                                                                                                             +
       'marketplace_account_id', marketplace_account_id,                                                                                                                                                        +
       'marketplace', marketplace,                                                                                                                                                                              +
       'marketplace_sku', marketplace_seller_sku,                                                                                                                                                               +
       'marketplace_sku_id', marketplace_sku_id,                                                                                                                                                                +
       'marketplace_seller_sku', marketplace_seller_sku,                                                                                                                                                        +
       'local_sku', local_sku,                                                                                                                                                                                  +
       'product_name', product_name,                                                                                                                                                                            +
       'variant_name', variant_name,                                                                                                                                                                            +
       'unit_hpp', unit_hpp,                                                                                                                                                                                    +
       'hpp_total', hpp_total,                                                                                                                                                                                  +
                                                                                                                                                                                                                +
       'paid_rows', paid_rows,                                                                                                                                                                                  +
       'unpaid_rows', unpaid_rows,                                                                                                                                                                              +
       'paid_qty', paid_qty,                                                                                                                                                                                    +
       'unpaid_qty', unpaid_qty,                                                                                                                                                                                +
                                                                                                                                                                                                                +
       'settled_qty', paid_qty,                                                                                                                                                                                 +
       'qty_unpaid', unpaid_qty,                                                                                                                                                                                +
       'paid_total', paid_rows,                                                                                                                                                                                 +
       'unpaid_total', unpaid_rows,                                                                                                                                                                             +
                                                                                                                                                                                                                +
       'paid_gross_total', paid_gross_total,                                                                                                                                                                    +
       'unpaid_gross_total', unpaid_gross_total,                                                                                                                                                                +
       'paid_payout_total', paid_payout_total,                                                                                                                                                                  +
                                                                                                                                                                                                                +
       'all_rows', all_rows,                                                                                                                                                                                    +
       'all_qty', all_qty                                                                                                                                                                                       +
     ) order by all_qty desc, product_name, variant_name), '[]'::jsonb)                                                                                                                                         +
   )                                                                                                                                                                                                            +
   into v_result                                                                                                                                                                                                +
   from grouped;                                                                                                                                                                                                +
                                                                                                                                                                                                                +
   return coalesce(v_result, jsonb_build_object(                                                                                                                                                                +
     'ok', true,                                                                                                                                                                                                +
     'version', 'finance_sku_payout_count_summary_2026_07_06_v6_clean_skus',                                                                                                                                    +
     'start', v_start,                                                                                                                                                                                          +
     'end', v_end,                                                                                                                                                                                              +
     'rows', '[]'::jsonb                                                                                                                                                                                        +
   ));                                                                                                                                                                                                          +
 end;                                                                                                                                                                                                           +
 $function$                                                                                                                                                                                                     +
 

 CREATE OR REPLACE FUNCTION public.finance_sku_order_details_core_v3(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)                                                            +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);                                                                                                                                                                                                                                                                                                                                                                                        +
   v_tenant_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_role text;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   v_start date := coalesce(p_start, date_trunc('month', timezone('Asia/Jakarta', now()))::date);                                                                                                                                                                                                                                                                                                                                                                                                  +
   v_end date := coalesce(p_end, timezone('Asia/Jakarta', now())::date);                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_start_ts timestamptz;                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   v_end_ts timestamptz;                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_marketplace text;                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_account_id uuid := p_account_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
   v_marketplace_sku text := lower(nullif(trim(coalesce(p_marketplace_sku, '')), ''));                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_local_sku text := lower(nullif(trim(coalesce(p_local_sku, '')), ''));                                                                                                                                                                                                                                                                                                                                                                                                                         +
   v_search text := lower(nullif(trim(coalesce(p_search, '')), ''));                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_filter text := lower(trim(coalesce(p_payout_filter, 'all')));                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   v_page integer := greatest(coalesce(p_page, 1), 1);                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_page_size integer := least(greatest(coalesce(p_page_size, 20), 1), 25);                                                                                                                                                                                                                                                                                                                                                                                                                       +
   v_offset integer;                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_detail_mode boolean;                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   perform set_config('work_mem', '64MB', true);                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     coalesce(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
       case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         when (v_claims->>'tenant_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'                                                                                                                                                                                                                                                                                                                                                                                         +
         then (v_claims->>'tenant_id')::uuid                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         else null::uuid                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
       (select u.tenant_id from public.users u where u.user_id = auth.uid() limit 1)                                                                                                                                                                                                                                                                                                                                                                                                               +
     ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
     coalesce(nullif(v_claims->>'role', ''), '')                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   into v_tenant_id, v_role;                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   v_start_ts := (v_start::timestamp at time zone 'Asia/Jakarta');                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   v_end_ts := ((v_end + 1)::timestamp at time zone 'Asia/Jakarta');                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_offset := (v_page - 1) * v_page_size;                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   v_filter := case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     when v_filter in ('settled', 'released', 'release', 'payout', 'paid payout', 'sudah payout') then 'paid'                                                                                                                                                                                                                                                                                                                                                                                      +
     when v_filter in ('pending', 'belum payout', 'no payout', 'missing payout') then 'unpaid'                                                                                                                                                                                                                                                                                                                                                                                                     +
     when v_filter = '' then 'all'                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
     else v_filter                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   v_marketplace := case                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     when lower(regexp_replace(coalesce(p_marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%shopee%' then 'shopee'                                                                                                                                                                                                                                                                                                                                                                                  +
     when lower(regexp_replace(coalesce(p_marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%tiktok%' then 'tiktok'                                                                                                                                                                                                                                                                                                                                                                                  +
     else null                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   v_detail_mode := v_marketplace_sku is not null                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
     or v_local_sku is not null                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     or v_search is not null;                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   if v_role <> 'service_role' and v_tenant_id is null then                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     return jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
       'rows', '[]'::jsonb,                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
       'page', v_page,                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
       'page_size', v_page_size,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       'total', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
       'total_count', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       'total_pages', 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       'source', 'finance_sku_order_details_fast_mtd'                                                                                                                                                                                                                                                                                                                                                                                                                                              +
     );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   if v_detail_mode and v_marketplace_sku = 'missing_or_adjustment' then                                                                                                                                                                                                                                                                                                                                                                                                                           +
     return (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
       with finance_adjustments as (                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
         select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           tenant_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           marketplace_account_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           marketplace,                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           coalesce(nullif(order_id, ''), 'ADJ-' || md5(random()::text)) as order_key,                                                                                                                                                                                                                                                                                                                                                                                                             +
           gross_amount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           payout_amount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           net_settlement,                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           settlement_date,                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           period_start                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
         from public.marketplace_finance_reports fr                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         where tenant_id = v_tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           and (v_marketplace is null or lower(coalesce(marketplace, '')) like '%' || v_marketplace || '%')                                                                                                                                                                                                                                                                                                                                                                                        +
           and (v_account_id is null or marketplace_account_id = v_account_id)                                                                                                                                                                                                                                                                                                                                                                                                                     +
           and coalesce(settlement_date, period_start) >= v_start                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           and coalesce(settlement_date, period_start) <= v_end                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           and not exists (                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             select 1 from public.marketplace_orders o                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             where o.tenant_id = fr.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
               and coalesce(nullif(o.external_order_id, ''), nullif(o.order_sn, ''), o.marketplace_order_id::text) = coalesce(nullif(fr.order_id, ''), fr.marketplace_order_id::text)                                                                                                                                                                                                                                                                                                              +
           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       paged as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         select *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from finance_adjustments                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         order by coalesce(settlement_date, period_start) desc, order_key                                                                                                                                                                                                                                                                                                                                                                                                                          +
         offset v_offset                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         limit v_page_size                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         'rows', coalesce(jsonb_agg(jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'source', 'finance_sku_order_details_fast_mtd_detail',                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'order_id', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order_sn', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'marketplace_order_id', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'marketplace_order_item_id', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'resi', '-',                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'tracking_number', '-',                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'order_date', coalesce(settlement_date, period_start),                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order_created_at', coalesce(settlement_date, period_start),                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'marketplace', marketplace,                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'marketplace_account_id', marketplace_account_id,                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'local_sku', 'Unmapped',                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           'sku', 'missing_or_adjustment',                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           'marketplace_sku_id', 'missing_or_adjustment',                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'marketplace_sku', 'missing_or_adjustment',                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'marketplace_seller_sku', 'missing_or_adjustment',                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'product_name', 'Platform Adjustment / Missing Order',                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'variant_name', 'N/A',                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'marketplace_variation_name', 'N/A',                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           'qty', 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'quantity', 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'gross', coalesce(gross_amount, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'gross_amount', coalesce(gross_amount, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           'gross_total', coalesce(gross_amount, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'gross_per_item', coalesce(gross_amount, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'payout', coalesce(payout_amount, net_settlement, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'payout_amount', coalesce(payout_amount, net_settlement, 0),                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'payout_per_item', coalesce(payout_amount, net_settlement, 0),                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'hpp', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'hpp_total', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           'hpp_per_item', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'unit_hpp', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'hpp_status', 'HPP belum mapping',                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'target_margin_percent', 0,                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'finance_status', 'SETTLED',                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'payout_status', 'SETTLED'                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         ) order by coalesce(settlement_date, period_start) desc, order_key), '[]'::jsonb),                                                                                                                                                                                                                                                                                                                                                                                                        +
         'page', v_page,                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         'page_size', v_page_size,                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         'total', (select count(*) from finance_adjustments),                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         'total_count', (select count(*) from finance_adjustments),                                                                                                                                                                                                                                                                                                                                                                                                                                +
         'total_pages', greatest(1, ceil((select count(*) from finance_adjustments)::numeric / v_page_size)::integer),                                                                                                                                                                                                                                                                                                                                                                             +
         'source', 'finance_sku_order_details_fast_mtd'                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   if v_detail_mode then                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     return (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
       with order_base as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         select *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             o.marketplace_order_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             o.tenant_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             o.marketplace_account_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             o.order_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             timezone('Asia/Jakarta', o.order_created_at)::date as order_date,                                                                                                                                                                                                                                                                                                                                                                                                                     +
             coalesce(nullif(o.order_id::text, ''), nullif(o.order_sn::text, ''), nullif(o.external_order_id::text, ''), o.marketplace_order_id::text) as order_key,                                                                                                                                                                                                                                                                                                                               +
             coalesce(nullif(o.order_sn::text, ''), nullif(o.external_order_id::text, ''), nullif(o.order_id::text, '')) as order_sn,                                                                                                                                                                                                                                                                                                                                                              +
             coalesce(nullif(o.tracking_number, ''), nullif(o.label_code, ''), nullif(o.package_id, '')) as tracking_number,                                                                                                                                                                                                                                                                                                                                                                       +
             lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) as status_text,                                                                                                                                                                                                                                                                                                                                                         +
             coalesce(nullif(o.gross_amount, 0), nullif(o.total_amount, 0), nullif(o.paid_amount, 0), 0)::numeric as order_gross,                                                                                                                                                                                                                                                                                                                                                                  +
             case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
               when lower(regexp_replace(coalesce(o.marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%shopee%' then 'shopee'                                                                                                                                                                                                                                                                                                                                                                        +
               when lower(regexp_replace(coalesce(o.marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%tiktok%' then 'tiktok'                                                                                                                                                                                                                                                                                                                                                                        +
               else lower(regexp_replace(coalesce(o.marketplace, 'unknown'), '[^a-z0-9]+', '', 'g'))                                                                                                                                                                                                                                                                                                                                                                                               +
             end as marketplace_group                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           from public.marketplace_orders o                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           where coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) >= v_start_ts                                                                                                                                                                                                                                                                                                                                                                                               +
       and coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) < v_end_ts                                                                                                                                                                                                                                                                                                                                                                                                        +
             and (v_role = 'service_role' or o.tenant_id = v_tenant_id)                                                                                                                                                                                                                                                                                                                                                                                                                            +
             and (v_account_id is null or o.marketplace_account_id = v_account_id)                                                                                                                                                                                                                                                                                                                                                                                                                 +
         ) o                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         where (v_marketplace is null or v_marketplace = '' or o.marketplace_group = public._finance_marketplace_norm_20260624(v_marketplace))                                                                                                                                                                                                                                                                                                                                                     +
           and o.status_text not like '%cancel%'                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           and o.status_text not like '%batal%'                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           and o.status_text not like '%unpaid%'                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           and o.status_text not like '%in_cancel%'                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           and o.status_text not like '%refund%'                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           and o.status_text not like '%return%'                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       finance_by_order as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           ob.marketplace_order_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           coalesce(sum(coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0)), 0)::numeric as payout,                                                                                                                                                                                                                                                                                                                                                                              +
           coalesce(sum(coalesce(fr.gross_amount, fr.gross_sales, 0)), 0)::numeric as finance_gross,                                                                                                                                                                                                                                                                                                                                                                                               +
           coalesce(sum(coalesce(fr.platform_fee, 0)), 0)::numeric as platform_fee,                                                                                                                                                                                                                                                                                                                                                                                                                +
           coalesce(sum(coalesce(fr.commission_fee, 0)), 0)::numeric as commission_fee,                                                                                                                                                                                                                                                                                                                                                                                                            +
           coalesce(sum(coalesce(fr.affiliate_fee, 0)), 0)::numeric as affiliate_fee,                                                                                                                                                                                                                                                                                                                                                                                                              +
           coalesce(sum(coalesce(fr.shipping_fee, 0)), 0)::numeric as shipping_fee,                                                                                                                                                                                                                                                                                                                                                                                                                +
           coalesce(sum(coalesce(fr.discount_amount, 0)), 0)::numeric as discount_amount,                                                                                                                                                                                                                                                                                                                                                                                                          +
           coalesce(sum(coalesce(fr.voucher_amount, 0)), 0)::numeric as voucher_amount,                                                                                                                                                                                                                                                                                                                                                                                                            +
           coalesce(sum(coalesce(fr.refund_amount, 0)), 0)::numeric as refund_amount,                                                                                                                                                                                                                                                                                                                                                                                                              +
           coalesce(sum(coalesce(fr.adjustment_amount, 0)), 0)::numeric as adjustment_amount                                                                                                                                                                                                                                                                                                                                                                                                       +
         from order_base ob                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         join                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           select tenant_id, marketplace_account_id, marketplace, order_id, marketplace_order_id, gross_amount, gross_sales, payout_amount, received_amount, net_settlement, platform_fee, commission_fee, affiliate_fee, shipping_fee, discount_amount, voucher_amount, refund_amount, adjustment_amount                                                                                                                                                                                          +
           from public.marketplace_finance_reports                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           where lower(coalesce(marketplace, '')) not in ('tiktok', 'tiktok_shop')                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           union all                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           select tenant_id, marketplace_account_id, marketplace, coalesce(nullif(order_id, ''), nullif(order_sn, ''), nullif(external_order_id, '')) as order_id, marketplace_order_id, gross_amount, gross_amount as gross_sales, received_amount as payout_amount, received_amount, net_settlement, null as platform_fee, null as commission_fee, null as affiliate_fee, null as shipping_fee, null as discount_amount, null as voucher_amount, null as refund_amount, null as adjustment_amount+
           from public.marketplace_finance_items                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           where lower(coalesce(marketplace, '')) in ('tiktok', 'tiktok_shop')                                                                                                                                                                                                                                                                                                                                                                                                                     +
         ) fr                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           on fr.tenant_id = ob.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
          and fr.marketplace_account_id = ob.marketplace_account_id                                                                                                                                                                                                                                                                                                                                                                                                                                +
          and fr.order_id = ob.order_key                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         group by ob.marketplace_order_id                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       line_base as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           ob.*,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           oi.marketplace_order_item_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           coalesce(nullif(oi.marketplace_sku_id, ''), nullif(oi.remote_sku_id, '')) as marketplace_sku_id,                                                                                                                                                                                                                                                                                                                                                                                        +
           coalesce(nullif(oi.marketplace_sku, ''), nullif(oi.marketplace_sku_id, ''), nullif(oi.remote_sku_id, '')) as marketplace_sku,                                                                                                                                                                                                                                                                                                                                                           +
           coalesce(nullif(oi.marketplace_seller_sku, ''), nullif(oi.seller_sku, '')) as marketplace_seller_sku,                                                                                                                                                                                                                                                                                                                                                                                   +
           coalesce(nullif(oi.local_sku, ''), nullif(oi.mapped_local_sku, '')) as local_sku,                                                                                                                                                                                                                                                                                                                                                                                                       +
           coalesce(nullif(oi.marketplace_product_name, ''), nullif(oi.product_name, ''), nullif(oi.local_product_name, '')) as product_name,                                                                                                                                                                                                                                                                                                                                                      +
           coalesce(nullif(oi.marketplace_variant_name, ''), nullif(oi.variant_name, ''), nullif(oi.variation_name, '')) as variant_name,                                                                                                                                                                                                                                                                                                                                                          +
           greatest(coalesce(nullif(oi.qty, 0), nullif(oi.quantity, 0), 1), 1)::numeric as qty,                                                                                                                                                                                                                                                                                                                                                                                                    +
           coalesce(                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             nullif(oi.gross_amount, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             nullif(oi.paid_amount, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             nullif(oi.unit_gross_amount, 0) * greatest(coalesce(nullif(oi.qty, 0), nullif(oi.quantity, 0), 1), 1),                                                                                                                                                                                                                                                                                                                                                                                +
             0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           )::numeric as line_gross                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         from order_base ob                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         join public.marketplace_order_items oi                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           on oi.tenant_id = ob.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
          and oi.marketplace_order_id = ob.marketplace_order_id                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         where (v_marketplace_sku is null or v_marketplace_sku in (                                                                                                                                                                                                                                                                                                                                                                                                                                +
             lower(coalesce(oi.marketplace_sku_id, '')),                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             lower(coalesce(oi.marketplace_sku, '')),                                                                                                                                                                                                                                                                                                                                                                                                                                              +
             lower(coalesce(oi.remote_sku_id, '')),                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             lower(coalesce(oi.marketplace_seller_sku, '')),                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             lower(coalesce(oi.seller_sku, ''))                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           ))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           and (v_local_sku is null or v_local_sku = lower(coalesce(oi.local_sku, oi.mapped_local_sku, '')))                                                                                                                                                                                                                                                                                                                                                                                       +
           and (v_search is null or lower(concat_ws(' ', ob.order_key, ob.order_sn, ob.tracking_number, oi.marketplace_sku_id, oi.marketplace_sku, oi.marketplace_seller_sku, oi.seller_sku, oi.local_sku, oi.mapped_local_sku, oi.marketplace_product_name, oi.product_name, oi.marketplace_variant_name, oi.variant_name)) like '%' || v_search || '%')                                                                                                                                          +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       line_calc as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         select lb.*, sum(lb.line_gross) over (partition by lb.marketplace_order_id) as order_line_gross                                                                                                                                                                                                                                                                                                                                                                                           +
         from line_base lb                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       enriched_base as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
         select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           lc.*,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           coalesce(f.payout, 0)::numeric as order_payout,                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           (coalesce(f.payout, 0) <> 0) as has_payout                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         from line_calc lc                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         left join finance_by_order f on f.marketplace_order_id = lc.marketplace_order_id                                                                                                                                                                                                                                                                                                                                                                                                          +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       filtered as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
         select *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from enriched_base                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         where (v_filter = 'all' or (v_filter = 'paid' and has_payout) or (v_filter = 'unpaid' and not has_payout))                                                                                                                                                                                                                                                                                                                                                                                +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       counted as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         select filtered.*, count(*) over ()::integer as total_count                                                                                                                                                                                                                                                                                                                                                                                                                               +
         from filtered                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       paged as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         select *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from counted                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         order by order_created_at desc, order_key                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         offset v_offset                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         limit v_page_size                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       hpp_sku as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         select tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, '')) as marketplace_sku_id,                                                                                                                                                                                                                                                                                                                                                                                    +
                max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,                                                                                                                                                                                                                                                                                                                                                                                                                   +
                max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin                                                                                                                                                                                                                                                                                                                                                                                                   +
         from public.marketplace_variant_hpp_mappings                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         where coalesce(is_active, true) is true and nullif(marketplace_sku_id, '') is not null                                                                                                                                                                                                                                                                                                                                                                                                    +
           and (v_role = 'service_role' or tenant_id = v_tenant_id)                                                                                                                                                                                                                                                                                                                                                                                                                                +
         group by tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, ''))                                                                                                                                                                                                                                                                                                                                                                                                         +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       hpp_seller as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         select tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, '')) as marketplace_seller_sku,                                                                                                                                                                                                                                                                                                                                                                            +
                max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,                                                                                                                                                                                                                                                                                                                                                                                                                   +
                max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin                                                                                                                                                                                                                                                                                                                                                                                                   +
         from public.marketplace_variant_hpp_mappings                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         where coalesce(is_active, true) is true and nullif(marketplace_seller_sku, '') is not null                                                                                                                                                                                                                                                                                                                                                                                                +
           and (v_role = 'service_role' or tenant_id = v_tenant_id)                                                                                                                                                                                                                                                                                                                                                                                                                                +
         group by tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, ''))                                                                                                                                                                                                                                                                                                                                                                                                     +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       hpp_local as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         select tenant_id, marketplace_account_id, lower(nullif(local_sku, '')) as local_sku,                                                                                                                                                                                                                                                                                                                                                                                                      +
                max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,                                                                                                                                                                                                                                                                                                                                                                                                                   +
                max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin                                                                                                                                                                                                                                                                                                                                                                                                   +
         from public.marketplace_variant_hpp_mappings                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         where coalesce(is_active, true) is true and nullif(local_sku, '') is not null                                                                                                                                                                                                                                                                                                                                                                                                             +
           and (v_role = 'service_role' or tenant_id = v_tenant_id)                                                                                                                                                                                                                                                                                                                                                                                                                                +
         group by tenant_id, marketplace_account_id, lower(nullif(local_sku, ''))                                                                                                                                                                                                                                                                                                                                                                                                                  +
       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       paged_enriched as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           p.*,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           coalesce(hs.hpp, hsel.hpp, hl.hpp, 0)::numeric as unit_hpp,                                                                                                                                                                                                                                                                                                                                                                                                                             +
           coalesce(hs.target_margin, hsel.target_margin, hl.target_margin, 0)::numeric as target_margin                                                                                                                                                                                                                                                                                                                                                                                           +
         from paged p                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         left join public.marketplace_variant_hpp_mappings hpp                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           on hpp.tenant_id = p.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
          and (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
            (p.marketplace_group = 'shopee' and hpp.marketplace = 'shopee')                                                                                                                                                                                                                                                                                                                                                                                                                        +
            or (p.marketplace_group = 'tiktok_shop' and hpp.marketplace = 'tiktok_shop')                                                                                                                                                                                                                                                                                                                                                                                                           +
          )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
          and coalesce(nullif(p.marketplace_sku_id, ''), p.marketplace_product_id) = coalesce(nullif(hpp.marketplace_variant_id, ''), hpp.marketplace_product_id)                                                                                                                                                                                                                                                                                                                                  +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         'rows', coalesce(jsonb_agg(jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'source', 'finance_sku_order_details_fast_mtd_detail',                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'order_id', order_key,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order_sn', order_sn,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'marketplace_order_id', marketplace_order_id,                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           'marketplace_order_item_id', marketplace_order_item_id,                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'resi', tracking_number,                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           'tracking_number', tracking_number,                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'order_date', order_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           'order_created_at', order_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'marketplace', marketplace_group,                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'marketplace_account_id', marketplace_account_id,                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'local_sku', coalesce(nullif(local_sku, ''), '-'),                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'sku', coalesce(nullif(local_sku, ''), nullif(marketplace_sku_id, ''), nullif(marketplace_seller_sku, ''), '-'),                                                                                                                                                                                                                                                                                                                                                                        +
           'marketplace_sku_id', marketplace_sku_id,                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'marketplace_sku', marketplace_sku,                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'marketplace_seller_sku', marketplace_seller_sku,                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'product_name', product_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           'variant_name', variant_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           'marketplace_variation_name', variant_name,                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'qty', qty,                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'quantity', qty,                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           'gross', line_gross,                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           'gross_amount', line_gross,                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'gross_total', line_gross,                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           'gross_per_item', case when qty > 0 then line_gross / qty else 0 end,                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'payout', case when has_payout and order_line_gross > 0 then order_payout * (line_gross / order_line_gross) else 0 end,                                                                                                                                                                                                                                                                                                                                                                 +
           'payout_amount', case when has_payout and order_line_gross > 0 then order_payout * (line_gross / order_line_gross) else 0 end,                                                                                                                                                                                                                                                                                                                                                          +
           'payout_per_item', case when has_payout and order_line_gross > 0 and qty > 0 then (order_payout * (line_gross / order_line_gross)) / qty else 0 end,                                                                                                                                                                                                                                                                                                                                    +
           'hpp', unit_hpp * qty,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'hpp_total', unit_hpp * qty,                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'hpp_per_item', unit_hpp,                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'unit_hpp', unit_hpp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'hpp_status', case when unit_hpp > 0 then 'HPP mapping' else 'HPP belum mapping' end,                                                                                                                                                                                                                                                                                                                                                                                                   +
           'target_margin_percent', target_margin,                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'finance_status', case when has_payout then 'SETTLED' else 'PENDING_PAYOUT' end,                                                                                                                                                                                                                                                                                                                                                                                                        +
           'payout_status', case when has_payout then 'SETTLED' else 'PENDING_PAYOUT' end                                                                                                                                                                                                                                                                                                                                                                                                          +
         ) order by order_created_at desc, order_key), '[]'::jsonb),                                                                                                                                                                                                                                                                                                                                                                                                                               +
         'page', v_page,                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         'page_size', v_page_size,                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         'total', coalesce(max(total_count), 0),                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         'total_count', coalesce(max(total_count), 0),                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         'total_pages', greatest(1, ceil(coalesce(max(total_count), 0)::numeric / v_page_size)::integer),                                                                                                                                                                                                                                                                                                                                                                                          +
         'source', 'finance_sku_order_details_fast_mtd'                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       from paged_enriched                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   return jsonb_build_object('ok', true);                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.finance_sku_order_details(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)                                                                    +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  SET statement_timeout TO '25s'                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 declare\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);\r                                                                                                                                                                                                                                                                                                                                                                                      +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_user_id uuid;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_tenant_id uuid;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_role text := coalesce(nullif(v_claims->>'role',''), '');\r                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_start date := coalesce(p_start, date_trunc('month', now() at time zone 'Asia/Jakarta')::date);\r                                                                                                                                                                                                                                                                                                                                                                                              +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_end date := coalesce(p_end, (now() at time zone 'Asia/Jakarta')::date);\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_start_ts timestamptz := (coalesce(p_start, date_trunc('month', now() at time zone 'Asia/Jakarta')::date)::timestamp at time zone 'Asia/Jakarta');\r                                                                                                                                                                                                                                                                                                                                           +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_end_ts timestamptz := ((coalesce(p_end, (now() at time zone 'Asia/Jakarta')::date) + 1)::timestamp at time zone 'Asia/Jakarta');\r                                                                                                                                                                                                                                                                                                                                                            +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_marketplace text := public._finance_marketplace_norm_20260624(p_marketplace);\r                                                                                                                                                                                                                                                                                                                                                                                                               +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_account_id uuid := p_account_id;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_msku text := lower(nullif(trim(coalesce(p_marketplace_sku,'')), ''));\r                                                                                                                                                                                                                                                                                                                                                                                                                       +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_lsku text := lower(nullif(trim(coalesce(p_local_sku,'')), ''));\r                                                                                                                                                                                                                                                                                                                                                                                                                             +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_search text := lower(nullif(trim(coalesce(p_search,'')), ''));\r                                                                                                                                                                                                                                                                                                                                                                                                                              +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_filter text := lower(trim(coalesce(p_payout_filter,'all')));\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_page integer := greatest(coalesce(p_page,1),1);\r                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_page_size integer := least(greatest(coalesce(p_page_size,20),1),25);\r                                                                                                                                                                                                                                                                                                                                                                                                                        +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_offset integer := (greatest(coalesce(p_page,1),1)-1) * least(greatest(coalesce(p_page_size,20),1),25);\r                                                                                                                                                                                                                                                                                                                                                                                      +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_detail boolean;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_core jsonb;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_core_rows integer := 0;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_core_has_weak_fields boolean := false;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_result jsonb;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 begin\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_detail := v_msku is not null or v_lsku is not null or v_search is not null;\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   if not v_detail then\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     return public.finance_sku_order_details_group_20260625(\r                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
       p_start,p_end,p_marketplace,p_account_id,p_marketplace_sku,p_local_sku,p_search,p_payout_filter,p_page,p_page_size\r                                                                                                                                                                                                                                                                                                                                                                        +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     );\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_core := public.finance_sku_order_details_core_v3(\r                                                                                                                                                                                                                                                                                                                                                                                                                                           +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     p_start,p_end,p_marketplace,p_account_id,p_marketplace_sku,p_local_sku,p_search,p_payout_filter,p_page,p_page_size\r                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   );\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_core_rows := coalesce(jsonb_array_length(coalesce(v_core->'rows','[]'::jsonb)),0);\r                                                                                                                                                                                                                                                                                                                                                                                                          +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
